// Playwright fixtures (ARCHITECTURE section 24.2). Import `test` and `expect` from here in every spec:
//
//   import { test, expect } from "../fixtures";
//   test("books the seeded event", async ({ page, api, seed, loginAs, outbox, axe }) => {
//     await api.reset();
//     await seed("owner");
//     await loginAs(page, "owner@example.com");
//     ...
//     await axe(page);
//   });
//
// Every call to /api/test/* carries the per-run x-e2e-secret generated by playwright.config.ts.
import AxeBuilder from "@axe-core/playwright";
import { test as base, expect, type APIRequestContext, type APIResponse, type Page } from "@playwright/test";

export { expect };

export const E2E_SECRET_HEADER = "x-e2e-secret";

export type SeedScenario = "owner" | "team" | "empty";

export type OutboxEmail = {
  id: string;
  to: string[];
  cc: string[];
  from: string;
  replyTo: string | null;
  subject: string;
  text: string;
  html: string;
  template: string;
  category: string;
  status: string;
  icsMethod: string | null;
  hasIcs: boolean;
  links: string[];
  scheduledEventId: string | null;
  inviteeId: string | null;
  createdAt: string;
};

export type FakeCalendarEvent = { start: string; end: string; title?: string | null; allDay?: boolean; busy?: boolean };

export type TestApi = {
  /** Truncates every table (keeps generated secrets) and restores real time. */
  reset(): Promise<void>;
  /**
   * Seeds a scenario of scripts/seed-scenarios.ts (same code as `npm run db:seed`) and returns the seeded ids:
   * { ok, scenario, demo, owner?: { userId, organizationId, slug, scheduleIds, eventTypeIds }, team?: { teamId, slug,
   * memberIds, eventTypeIds }, demoData?: { scheduledEventIds, inviteeIds, contactIds } }. `demo` adds the --demo extras.
   */
  seed(scenario: SeedScenario, opts?: { demo?: boolean }): Promise<Record<string, unknown>>;
  /** Runs due jobs now (the in-process poller is off in E2E mode). */
  runJobs(opts?: { types?: string[]; maxJobs?: number }): Promise<Record<string, unknown>>;
  /** Latest emails, newest first, optionally to one address or of one template. */
  outbox(opts?: { to?: string; template?: string; limit?: number }): Promise<OutboxEmail[]>;
  /** Waits until an email matching the predicate arrives (polls the outbox). */
  waitForEmail(predicate: (e: OutboxEmail) => boolean, opts?: { to?: string; timeoutMs?: number }): Promise<OutboxEmail>;
  /** Injects external busy events for a user (fake calendar). */
  fakeCalendar(input: { email?: string; userId?: string; events: FakeCalendarEvent[]; replace?: boolean }): Promise<void>;
  /** Sets the business clock (now()) to an instant; null restores real time. */
  setTime(instant: string | Date | null): Promise<{ now: string; offsetMs: number }>;
  /** Moves the business clock by milliseconds. */
  advanceTime(ms: number): Promise<{ now: string; offsetMs: number }>;
  /** Raw request to any /api/test path with the secret header. */
  call(method: "GET" | "POST" | "DELETE", path: string, data?: unknown): Promise<APIResponse>;
};

export function e2eSecret(): string {
  const secret = process.env.E2E_SECRET;
  if (!secret) throw new Error("E2E_SECRET is not set (run the suite through playwright.config.ts)");
  return secret;
}

async function ensureOk(res: APIResponse, what: string): Promise<APIResponse> {
  if (!res.ok()) throw new Error(`${what} failed: HTTP ${res.status()} ${await res.text()}`);
  return res;
}

export function createTestApi(request: APIRequestContext): TestApi {
  const headers = () => ({ [E2E_SECRET_HEADER]: e2eSecret() });
  const call: TestApi["call"] = (method, path, data) =>
    request.fetch(path.startsWith("/") ? path : `/api/test/${path}`, { method, headers: headers(), data });
  const api: TestApi = {
    call,
    async reset() {
      await ensureOk(await call("POST", "/api/test/reset"), "reset");
    },
    async seed(scenario, opts = {}) {
      return (await ensureOk(await call("POST", "/api/test/seed", { scenario, demo: opts.demo === true }), `seed(${scenario})`)).json();
    },
    async runJobs(opts = {}) {
      return (await ensureOk(await call("POST", "/api/test/run-jobs", opts), "run-jobs")).json();
    },
    async outbox(opts = {}) {
      const qs = new URLSearchParams();
      if (opts.to) qs.set("to", opts.to);
      if (opts.template) qs.set("template", opts.template);
      if (opts.limit) qs.set("limit", String(opts.limit));
      const res = await ensureOk(await call("GET", `/api/test/outbox?${qs}`), "outbox");
      return ((await res.json()) as { emails: OutboxEmail[] }).emails;
    },
    async waitForEmail(predicate, opts = {}) {
      const deadline = Date.now() + (opts.timeoutMs ?? 15_000);
      for (;;) {
        const found = (await api.outbox({ to: opts.to })).find(predicate);
        if (found) return found;
        if (Date.now() > deadline) throw new Error(`No matching email${opts.to ? ` to ${opts.to}` : ""} within timeout`);
        await api.runJobs().catch(() => undefined);
        await new Promise((r) => setTimeout(r, 500));
      }
    },
    async fakeCalendar(input) {
      await ensureOk(await call("POST", "/api/test/fake-calendar", input), "fake-calendar");
    },
    async setTime(instant) {
      const now = instant === null ? null : instant instanceof Date ? instant.toISOString() : instant;
      return (await ensureOk(await call("POST", "/api/test/time", { now }), "time")).json();
    },
    async advanceTime(ms) {
      return (await ensureOk(await call("POST", "/api/test/time", { advanceMs: ms }), "time")).json();
    },
  };
  return api;
}

type Fixtures = {
  api: TestApi;
  /** Logs the browser context in as the user with this email (session cookie via /api/test/login). */
  loginAs: (page: Page, email: string) => Promise<void>;
  /** Shortcut for api.seed(). */
  seed: (scenario: SeedScenario, opts?: { demo?: boolean }) => Promise<Record<string, unknown>>;
  /** Shortcut for api.outbox(). */
  outbox: TestApi["outbox"];
  /** Runs axe-core (WCAG 2 A and AA) on the current page and fails on violations. */
  axe: (page: Page, opts?: { include?: string; exclude?: string[]; disableRules?: string[] }) => Promise<void>;
};

export const test = base.extend<Fixtures>({
  api: async ({ request }, use) => {
    await use(createTestApi(request));
  },
  loginAs: async ({}, use) => {
    await use(async (page, email) => {
      // page.context().request shares the browser context's cookie jar, so the Set-Cookie lands in the page.
      const res = await page.context().request.post("/api/test/login", {
        headers: { [E2E_SECRET_HEADER]: e2eSecret() },
        data: { email },
      });
      await ensureOk(res, `login(${email})`);
    });
  },
  seed: async ({ api }, use) => {
    await use((scenario, opts) => api.seed(scenario, opts));
  },
  outbox: async ({ api }, use) => {
    await use((opts) => api.outbox(opts));
  },
  axe: async ({}, use) => {
    await use(async (page, opts = {}) => {
      let builder = new AxeBuilder({ page }).withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"]);
      if (opts.include) builder = builder.include(opts.include);
      for (const ex of opts.exclude ?? []) builder = builder.exclude(ex);
      if (opts.disableRules?.length) builder = builder.disableRules(opts.disableRules);
      const results = await builder.analyze();
      const summary = results.violations.map((v) => `${v.id} (${v.impact}): ${v.help} [${v.nodes.length} node(s)]`);
      expect(summary, "axe violations").toEqual([]);
    });
  },
});
